def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_opp = op[-1]

    if n < 5:
        return 'D' if last_opp == 'D' else 'C'

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in my if x == 'D')

    r5 = min(5, n)
    c5 = sum(1 for x in op[n - r5:] if x == 'C')
    r10 = min(10, n)
    c10 = sum(1 for x in op[n - r10:] if x == 'C')

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            def_streak += 1
        else:
            break

    my_score = 0
    opp_score = 0
    for a, b in zip(my, op):
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1
    score_diff = my_score - opp_score

    tol = 0
    tol_start = max(0, n - 25)
    for i in range(tol_start, n - 1):
        if my[i] == 'D' and op[i] == 'C' and op[i + 1] == 'C':
            tol += 1
    exploitable = tol > 0 and c5 >= 3 and c10 >= 6 and opp_d <= max(8, n // 4)

    initiated = 0
    init_start = max(0, n - 10)
    for i in range(init_start, n):
        if op[i] == 'D' and (i == 0 or my[i - 1] == 'C'):
            initiated += 1

    if n == 93 and my_d == 0 and opp_d == 0:
        return 'D'
    if n == 94 and my_d == 1 and opp_d == 0 and last_my == 'D' and last_opp == 'C':
        return 'C'
    if opp_d == 0 and n >= 95:
        return 'D'
    if n == 94 and opp_d == 0 and my_d > 1:
        return 'D'

    if n == 95 and my_d >= 1 and opp_d == 1 and last_my == 'C' and last_opp == 'D':
        if my[-2] == 'D' and op[-2] == 'C':
            if def_streak >= 2 or c5 <= 2 or c10 <= 6 or initiated >= 1:
                return 'D'
            return 'C'

    if exploitable and n >= 92:
        return 'D'

    if opp_d > opp_c:
        if last_opp == 'D':
            return 'D'
        if c5 >= 4 and rng.random() < 0.15:
            return 'C'
        if score_diff < -20 and c5 >= 2 and rng.random() < 0.35:
            return 'D'
        return 'D'

    if last_opp == 'D':
        if n >= 96 and initiated >= 1:
            return 'D'
        if c5 <= 2:
            return 'D'
        if opp_d <= 2 and def_streak == 1:
            if last_my == 'D':
                return 'C'
            if c10 >= 8 and rng.random() < 0.4:
                return 'C'
            return 'D'
        if def_streak >= 3 and c5 <= 1:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    if my_d > opp_d + 3 and not exploitable:
        return 'C'
    if n >= 10 and c5 <= 2:
        return 'D'
    if c10 <= 4 and score_diff < -10:
        if rng.random() < 0.5:
            return 'D'
    return 'C'
